extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena status_panel.tscn deve avviarsi senza errori di istanza nulla"):
		return
	var msg_label = get_prop(main, "message_label") as Label
	if check("msg_label_exists", msg_label != null, "La variabile message_label non deve essere null"):
		check("msg_text", msg_label.text == "Sistema pronto", "Il testo di message_label deve essere 'Sistema pronto'")
	var title_label = get_prop(main, "title_label") as Label
	if check("title_label_exists", title_label != null, "La variabile title_label non deve essere null"):
		check("title_text", title_label.text == "Comandante", "Il testo di title_label deve essere 'Comandante'")
	var bar = get_prop(main, "health_bar") as Sprite2D
	if check("bar_exists", bar != null, "La variabile health_bar non deve essere null"):
		check("bar_color", bar.modulate == Color.GREEN, "Il colore modulate di health_bar deve essere Color.GREEN")

